// 1. Create feature branch and make changes
// git checkout -b feature/add-order-validation

@Service
public class OrderService {
    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    public Order createOrder(OrderRequest request) {
        if (request.quantity() <= 0) {  // new validation logic
            throw new IllegalArgumentException("Quantity must be positive");
        }
        var order = new Order(null, request.item(), request.quantity());
        return orderRepository.save(order);  // save to database
    }
}

// 2. Push branch: git push origin feature/add-order-validation
// 3. Open PR on GitHub: "Add quantity validation to order creation"
// 4. Team reviews, CI runs tests, reviewer approves
// 5. Merge PR — changes now in main branch

// Feature branch commits:
// c1: "Add Order entity"
// c2: "Fix typo in Order"
// c3: "Add validation logic"

// MERGE COMMIT (preserves all commits + adds merge commit):
// main: ... -> c1 -> c2 -> c3 -> M ("Merge PR #42")

// SQUASH AND MERGE (combines into one commit):
// main: ... -> S ("Add order validation (#42)")
// Single commit with PR number, clean main history

// REBASE AND MERGE (replays commits linearly, no merge commit):
// main: ... -> c1' -> c2' -> c3'
// Commits rewritten with new hashes, linear timeline

@RestController
public class OrderController {
    // Regardless of merge strategy, the final code is identical
    @PostMapping("/orders")
    public Order createOrder(@RequestBody OrderRequest request) {
        return orderService.createOrder(request);  // this code works the same
    }
}

// git log --oneline on main shows different histories
// Merge: all branch commits visible
// Squash: one clean commit
// Rebase: branch commits linearized

// PR Title: Add quantity validation to order creation (JIRA-123)

// PR Description:
// **Problem**: Users can submit orders with negative or zero quantities,
// causing database errors and broken analytics.
//
// **Solution**: Added validation in OrderService to reject invalid quantities
// before saving to database. Returns 400 Bad Request with clear error message.
//
// **Testing**: Added unit tests for edge cases (zero, negative, MAX_VALUE).
// Manual test: POST /api/orders with quantity=-5 returns proper error.
//
// **Reviewer notes**: I chose IllegalArgumentException over custom exception
// to keep it simple. Open to discussion if we want domain-specific errors.

@Service
public class OrderService {
    public Order createOrder(OrderRequest request) {
        // New validation logic
        if (request.quantity() <= 0) {
            throw new IllegalArgumentException(
                "Order quantity must be positive, got: " + request.quantity()
            );
        }
        var order = new Order(null, request.item(), request.quantity());
        return orderRepository.save(order);
    }
}

// Test coverage included
// Changed files: 2 (OrderService.java, OrderServiceTest.java)
// Lines changed: +15 -3

// Original code in PR:
@Service
public class OrderService {
    public Order createOrder(OrderRequest request) {
        if (request.quantity() <= 0 || request.quantity() > 10000) {
            throw new IllegalArgumentException("Invalid quantity");
        }
        return orderRepository.save(new Order(null, request.item(), request.quantity()));
    }
}

// Reviewer comment: "Extract validation into separate method for testability"

// Updated code after addressing comment:
@Service
public class OrderService {
    public Order createOrder(OrderRequest request) {
        validateQuantity(request.quantity());  // extracted method
        var order = new Order(null, request.item(), request.quantity());
        return orderRepository.save(order);
    }

    private void validateQuantity(int quantity) {
        if (quantity <= 0 || quantity > 10000) {
            throw new IllegalArgumentException(
                "Quantity must be between 1 and 10000, got: " + quantity
            );
        }
    }
}

// Response in comment thread:
// "Done! Extracted validation to validateQuantity() method in commit abc1234.
// Also improved the error message to show the actual invalid value."
